do $$ declare n_all int; n_del int; begin
  select count(*) into n_all from kinetic_artworks;
  select count(*) into n_del from kinetic_artworks k
   where k.source_url is null or not exists (select 1 from _keep x where x.source_url = k.source_url);
  if n_all > 0 and n_del > n_all * 0.5 then
    raise exception '삭제 대상 %/% 행 — 상한(%) 초과로 중단. manifest 를 확인하세요', n_del, n_all, '50%';
  end if;
  raise notice 'seed_sync: 기존 % 행 중 % 행 삭제 예정', n_all, n_del;
end $$;

insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, thumbnail_url, display_url, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('젤리 (Jellies)', '메리 커티스 래트클리프 (Mary Curtis Ratcliff)', '반투명 원반들이 모노필라멘트에 매달려 공기 흐름에 천천히 회전하며 벽에 부드러운 그림자를 드리우는 매달림형 키네틱 조각.', 2018, '폴리에스터·타이벡에 아크릴과 잉크, 리넨, 스틸, 모노필라멘트 (56×66×62 in)', NULL, ARRAY['키네틱아트','모빌','그림자','스틸','래트클리프']::text[], 'https://images.kctikinec.cloud/cards/001.webp?v=bea396df3f', 'https://images.kctikinec.cloud/display/001.webp?v=ced239416f', 'https://images.kctikinec.cloud/works/001.jpg', 'https://images.kctikinec.cloud/texts/001.txt', NULL, 0.314, 'CC BY-SA 4.0', 'Mary Curtis Ratcliff / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:%22Jellies%22_by_Mary_Curtis_Ratcliff.jpg')
on conflict (source_url) do update set title = excluded.title, artist = excluded.artist, description = excluded.description, created_year = excluded.created_year, materials = excluded.materials, dimensions = excluded.dimensions, tags = excluded.tags, thumbnail_url = excluded.thumbnail_url, display_url = excluded.display_url, image_url = excluded.image_url, detail_text_url = excluded.detail_text_url, video_url = excluded.video_url, file_size_mb = excluded.file_size_mb, license = excluded.license, attribution = excluded.attribution, updated_at = now();
