insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, thumbnail_url, display_url, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('세 개의 선 (Three Lines)', '조지 리키 (George Rickey)', '숲을 배경으로 세 개의 가느다란 금속 막대가 한 지점에서 뻗어 나온 야외 조각으로, 바람에 따라 막대 끝이 서서히 흔들린다.', 2010, '스테인리스 스틸', NULL, ARRAY['키네틱아트','조각','바람','리키']::text[], 'https://images.kctikinec.cloud/cards/300.webp?v=66d1bb874c', 'https://images.kctikinec.cloud/display/300.webp?v=7f22c99a5f', 'https://images.kctikinec.cloud/works/300.jpg', 'https://images.kctikinec.cloud/texts/300.txt', NULL, 0.793, 'CC BY-SA 4.0', 'EgorovaSvetlana / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Path_DeCordova_Sculpture_Park_Lincoln.jpg')
