values ('오렌지 익스텐션 (Orange extension)', '헤수스 라파엘 소토 (Jesús Rafael Soto)', '천장에서 바닥까지 촘촘히 늘어선 주황색 금속 막대들이 겹겹이 배치되어, 관람자가 움직이면 막대 사이 간격과 색면이 흔들리듯 변화하는 시각적 환경 조각이다.', 1968, '목재 구조물, 채색 금속 막대, 종이', NULL, ARRAY['키네틱아트','소토','옵아트','설치미술','금속막대']::text[], 'https://images.kctikinec.cloud/cards/594.webp?v=a2301331b4', 'https://images.kctikinec.cloud/display/594.webp?v=56ac84d29c', 'https://images.kctikinec.cloud/works/594.jpg', 'https://images.kctikinec.cloud/texts/594.txt', NULL, 0.765, 'CC BY 2.0', 'JasonParis from Toronto, Canada / Flickr : Zagreb Museum of Contemporary Art / CC BY 2.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Orange_extension,_close_up.jpg')
on conflict (source_url) do update set title = excluded.title, artist = excluded.artist, description = excluded.description, created_year = excluded.created_year, materials = excluded.materials, dimensions = excluded.dimensions, tags = excluded.tags, thumbnail_url = excluded.thumbnail_url, display_url = excluded.display_url, image_url = excluded.image_url, detail_text_url = excluded.detail_text_url, video_url = excluded.video_url, file_size_mb = excluded.file_size_mb, license = excluded.license, attribution = excluded.attribution, updated_at = now();
