insert into kinetic_artworks (title, artist, description, created_year, materials, dimensions, tags, thumbnail_url, display_url, image_url, detail_text_url, video_url, file_size_mb, license, attribution, source_url)
values ('말레비치에게 바치는 경의, 비무랄 (Bimural de Victor Vasarely, Homenaje a Malevitch) - b면', '빅토르 바자렐리 (Victor Vasarely)', 'UCV 학사원 양면 벽화의 다른 한쪽 면으로, 노랑 바탕에 검정·갈색 도형이 배치되어 있고 벽 중간에 사각 개구부가 나 있다.', 1954, '세라믹 타일 벽화', NULL, ARRAY['키네틱아트','옵아트','타일벽화','바자렐리','기하학적추상']::text[], 'https://images.kctikinec.cloud/cards/604.webp?v=de825245d2', 'https://images.kctikinec.cloud/display/604.webp?v=ddbb516f3a', 'https://images.kctikinec.cloud/works/604.jpg', 'https://images.kctikinec.cloud/texts/604.txt', NULL, 0.532, 'CC BY-SA 4.0', 'GermanX / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:UCV_2015-042b_Bimural_de_Victor_Vasarely_1954,_Homenaje_a_Malevitch.JPG')
