values ('정원의 나무와 윈드차임', NULL, '영국 기버드 가든의 나무에 매달린 윈드차임이 바람에 흔들리며 소리를 낸다.', 2023, '금속(추정)', NULL, ARRAY['키네틱아트','바람','정원']::text[], 'https://images.kctikinec.cloud/cards/897.webp?v=b2f476130f', 'https://images.kctikinec.cloud/display/897.webp?v=fcceb065e8', 'https://images.kctikinec.cloud/works/897.jpg', 'https://images.kctikinec.cloud/texts/897.txt', NULL, 1.208, 'CC BY-SA 4.0', 'Acabashi / Own work / CC BY-SA 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tree_wind_chimes_Gibberd_Garden_Harlow_Essex_England.jpg')
