values ('꽃무늬 윈드차임', NULL, '꽃과 새 문양이 새겨진 둥근 상판 아래 청록빛 금속관 여러 개가 매달려 바람에 흔들리며 소리를 낸다.', 1927, '금속(청동 계열, 추정)', NULL, ARRAY['키네틱아트','바람','전통공예']::text[], 'https://images.kctikinec.cloud/cards/915.webp?v=24c4e8fd98', 'https://images.kctikinec.cloud/display/915.webp?v=a5599efc2c', 'https://images.kctikinec.cloud/works/915.jpg', 'https://images.kctikinec.cloud/texts/915.txt', NULL, 0.341, 'CC BY-SA 3.0', 'Dandy1022 / Own work / CC BY-SA 3.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Wind_chime.jpg')
