values ('풍향계(날개 달린 여인상)', NULL, '화살과 방향 지시침 아래 날개 달린 나체 여인상이 얹힌 풍향계로, 바람 방향에 따라 전체가 회전한다.', 1894, '금속 또는 석고 주조(추정)', NULL, ARRAY['키네틱아트','풍향계','조각','바람']::text[], 'https://images.kctikinec.cloud/cards/928.webp?v=36953cf8a9', 'https://images.kctikinec.cloud/display/928.webp?v=2d0552cf91', 'https://images.kctikinec.cloud/works/928.png', 'https://images.kctikinec.cloud/texts/928.txt', NULL, 0.26, 'CC BY 2.0', 'ketrin1407 / Escudero (full name and details unknown) - Weather Vane (1894) / CC BY 2.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Escudero_(full_name_and_details_unknown)_-_Weather_Vane_(1894)_(12023855056).png')
