values ('K''nex 스트랜드비스트 (K''nex Strandbeest)', NULL, 'K''nex 조립 부품만으로 만든 스트랜드비스트다. 파란색과 회색 막대가 관절로 연결되어 다리처럼 뻗어 있다.', NULL, 'K''nex 조립 플라스틱 부품', NULL, ARRAY['키네틱아트','스트랜드비스트','K''nex','조립','플라스틱']::text[], 'https://images.kctikinec.cloud/cards/371.webp?v=1762cd9cab', 'https://images.kctikinec.cloud/display/371.webp?v=590d4552f2', 'https://images.kctikinec.cloud/works/371.jpg', 'https://images.kctikinec.cloud/texts/371.txt', NULL, 0.61, 'CC BY-SA 3.0', 'Sean Corcoran / Own work / CC BY-SA 3.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:K%27nex_Strandbeest.jpg')
