values ('금속 스트랜드비스트 (Metal Strandbeest)', NULL, '금속 판재와 너트·볼트를 이용해 만든 단순한 스트랜드비스트다. 구멍이 뚫린 평평한 금속 막대들이 연결되어 링크 구조를 이룬다.', NULL, '금속 판재, 너트, 볼트', NULL, ARRAY['키네틱아트','스트랜드비스트','금속','링크구조','볼트']::text[], 'https://images.kctikinec.cloud/cards/373.webp?v=8ee8c1e321', 'https://images.kctikinec.cloud/display/373.webp?v=1f78367aa6', 'https://images.kctikinec.cloud/works/373.jpg', 'https://images.kctikinec.cloud/texts/373.txt', NULL, 0.453, 'CC BY-SA 3.0', 'Sean Corcoran / Own work / CC BY-SA 3.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Metal_Strandbeest.jpg')
