values ('프락시노스코프 (Praxinoscope)', NULL, '모스크바 영화박물관에 있는 프락시노스코프 전시물이다. 원통 안쪽에 말을 탄 사람들의 실루엣 그림이 연속으로 붙어 있다.', NULL, '미상', NULL, ARRAY['키네틱아트','광학장난감','프락시노스코프','영화사']::text[], 'https://images.kctikinec.cloud/cards/466.webp?v=d39015d2e6', 'https://images.kctikinec.cloud/display/466.webp?v=cf8133fc4c', 'https://images.kctikinec.cloud/works/466.jpg', 'https://images.kctikinec.cloud/texts/466.txt', NULL, 0.324, 'CC BY 4.0', 'Gerarus / Own work / CC BY 4.0 / via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Praxinoscope.jpg')
